    {"id": 5, "title": "Dune", "genre": "science fiction", "available": False}
]

users = [
    {"id": 100, "name": "Alice", "reserved_books": [101]},
    {"id": 200, "name": "Bob", "reserved_books": []}
]

def get_books_by_genre(genre: str) -> List[Dict[str, Union[int, str, bool]]]:
    """Return books filtered by genre"""
    return [book for book in books if book["genre"] == genre]

def check_availability(book_id: int) -> bool:
    """Check if a book is available by ID"""
