from typing import List, Dict, Optional

# Mocked data storage
flight_db = [
    {"id": "AA123", "date": "2023-10-10", "from": "NYC", "to": "Paris", "price": 550},
    {"id": "BA456", "date": "2023-10-10", "from": "NYC", "to": "Paris", "price": 600},
