]

hotel_db = [
    {"name": "Hotel A", "city": "Paris", "date": "2023-10-10", "price": 200, "rating": 4.5},
    {"name": "Hotel B", "city": "Paris", "date": "2023-10-10", "price": 150, "rating": 4.0},
    {"name": "Hotel C", "city": "London", "date": "2023-10-10", "price": 180, "rating": 4.7}
]

weather_db = [
    {"city": "Paris", "date": "2023-10-10", "condition": "sunny", "temp": 22},
    {"city": "London", "date": "2023-10-10", "condition": "rainy", "temp": 18}
]

# Core functions
def get_flights(date: str, origin: str) -> List[Dict]:
    """Get available flights by date and origin city"""
    return [f for f in flight_db if f["date"] == date and f["from"] == origin]

def get_hotels(city: str, date: str, max_price: Optional[float] = None) -> List[Dict]:
    """Find hotels in a city for specific date with optional price filter"""
    results = [h for h in hotel_db if h["city"] == city and h["date"] == date]
    if max_price is not None:
        results = [h for h in results if h["price"] <= max_price]
    return results

def get_weather(city: str, date: str) -> Optional[Dict]:
    """Retrieve weather forecast for a city on specific date"""
    return next((w for w in weather_db if w["city"] == city and w["date"] == date), None)

employees = [
    {"id": 1, "name": "John Doe", "department_id": 1},
    {"id": 2, "name": "Jane Smith", "department_id": 1},
    {"id": 3, "name": "Bob Wilson", "department_id": 2},
    {"id": 4, "name": "Alice Brown", "department_id": 2}
]

departments = [
    {"id": 1, "name": "Engineering", "budget": 100000},
    {"id": 2, "name": "Marketing", "budget": 50000}
]

projects = [
    {"id": 1, "name": "Product Launch", "employee_id": 3, "allocated_budget": 80000, "used_budget": 75000, "due_date": "2023-12-01", "status": "completed"},
    {"id": 2, "name": "Website Redesign", "employee_id": 3, "allocated_budget": 80000, "used_budget": 95000, "due_date": "2023-11-01", "status": "overdue"},
